class Resolution {
 public:
  static const Resolution& getInstance(int width = 0, int height = 0);

  const int& width() const {
    return imgWidth;
  }

  const int& height() const {
    return imgHeight;
  }

  const int& cols() const {
    return imgWidth;
  }

  const int& rows() const {
    return imgHeight;
  }

  const int& numPixels() const {
    return imgNumPixels;
  }

 private:
  Resolution(int width, int height)
      : imgWidth(width), imgHeight(height), imgNumPixels(width * height) {
    assert(width > 0 && height > 0 && "You haven't initialised the Resolution class!");
  }

  const int imgWidth;
  const int imgHeight;
  const int imgNumPixels;
};

class Intrinsics {
 public:
  static const Intrinsics& getInstance(float fx = 0, float fy = 0, float cx = 0, float cy = 0);

  const float& fx() const {
    return fx_;
  }

  const float& fy() const {
    return fy_;
  }

  const float& cx() const {
    return cx_;
  }

  const float& cy() const {
    return cy_;
  }

 private:
  Intrinsics(float fx, float fy, float cx, float cy) : fx_(fx), fy_(fy), cx_(cx), cy_(cy) {
    assert(fx != 0 && fy != 0 && "You haven't initialised the Intrinsics class!");
  }

  const float fx_, fy_, cx_, cy_;
};

